style.css:
/* Define a cor de fundo da página */
body {
  background-color: #f0f0f0;
}

/* Define o estilo dos títulos */
h1 {
  color: #333;
  font-family: Arial, sans-serif;
  text-align: center;
}

/* Define o estilo dos parágrafos */
p {
  color: #666;
  font-size: 16px;
  line-height: 1.5;
}
